SELECT NVL((CASE WHEN C.ACCT_SUBJECT_TYPE = #{finprodType,jdbcType=VARCHAR} THEN C.ACCT_SUBJECT_ID ELSE D.PORTFOLIO_ID END), C.ACCT_SUBJECT_ID) AS portfolioId,/**投资组合代码**/ B.BOOK_DATE AS cdate, /**日期**/ C.STANDARD_CCY AS ccy, /**估值币种**/ B.NET_ASSET_VALUE AS tdyAssetNetvalue, /**当日资产净值**/ (CASE WHEN B.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR} THEN B.NET_UNIT_VALUE ELSE B.P_YIELD END) AS tdyUnitValue, /**当日单位净值**/ (B.NET_UNIT_VALUE+B.TOT_BOUNS_NET) as tdyUnitValueSum, /**当日累计净值**/
B.PROFIT_TYPE AS profitType,/**收益类型**/ E.LEV AS lev, /**层级**/ B.BOOKSET_ID AS booksetId /**账套代码**/
FROM BOK_STAT_BOK_POSITION B INNER JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID AND NVL(C.ACCT_SUBJECT_TYPE,'') != 'F26' LEFT JOIN FIN_PRODUCT_ADD D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID INNER JOIN BOK_ACCT_LAYERING_INFO E ON B.BOOKSET_ID = E.BOOKSET_ID AND B.LAYERING_ID = E.LAYERING_ID AND E.LEV = '1' WHERE B.BOOKSET_DATE = #{booksetDate,jdbcType=DATE} AND B.BOOK_DATE = #{bookDate,jdbcType=DATE} AND B.HAPPEN_DATE = #{happenDate,jdbcType=DATE}
AND (B.BOOKSET_ID IN
null) OR B.BOOKSET_ID in (
#{item}
)

