case when BASE_SUBJECT_NATURE = 'YFZZDJSSXF' or BASE_SUBJECT_NATURE = 'YFZZDJYSXF' then '01' when BASE_SUBJECT_NATURE = 'YFSQSJSSXF' or BASE_SUBJECT_NATURE = 'YFSQSJYSXF' then '02' when BASE_SUBJECT_NATURE = 'YFZDJSSXF' then '03' ELSE '999999' END AS feePlace
