SELECT C.ACCT_SUBJECT_ID AS finprodId,/**金融产品代码**/ B.BALANCE_DATE AS cdate,/**日期**/ 0 AS branch,/**分支序号**/ (B.O_C_AMT - B.O_D_AMT) AS tdyUnpaidIntincexp,/**当日累计应付费用**/ (CASE WHEN B.SUBJECT_NO = '22210501' THEN 'TAX0102' WHEN B.SUBJECT_NO = '22210503' THEN 'TAX0202' WHEN B.SUBJECT_NO = '22210502' THEN 'TAX0302' WHEN B.SUBJECT_NO = '22210701' THEN 'ALT0102' WHEN B.SUBJECT_NO = '22210702' THEN 'ALT0202' WHEN B.SUBJECT_NO = '22210703' THEN 'ALT0302'
WHEN B.SUBJECT_NO = '22210704' THEN 'ALT0402'
ELSE NULL END) AS feeType,/**费用类型**/ D.P_FINPROD_ID AS pFinprodId /**母金融产品代码**/
FROM BOK_BOOKSET C INNER JOIN BOK_BALANCE B ON B.BOOKSET_ID = C.BOOKSET_ID LEFT JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID WHERE B.BALANCE_DATE = #{booksetDate,jdbcType=DATE}
AND B.SUBJECT_NO IN ('22210501','22210503','22210502','22210701','22210702','22210703','22210704')
AND NVL(C.ACCT_SUBJECT_TYPE,'') != 'F26'
AND (C.BOOKSET_ID IN
null) OR C.BOOKSET_ID in (
#{item}
)

