ELSE NVL(D.PORTFOLIO_ID,C.ACCT_SUBJECT_ID) END) AS portfolioId,/**投资组合代码**/ '999999' AS secAcctId,/**通道代码,pdm中说明，若无通道代码，塞入999999**/ #{booksetDate,jdbcType=DATE} AS cdate,/**日期**/ '999999' AS invAim /**投资目的,pdm中说明，若无投资目的，塞入999999**/ FROM BOK_BOOKSET C LEFT JOIN FIN_PRODUCT_ADD D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID WHERE NVL(C.ACCT_SUBJECT_TYPE,'') != 'F26'
AND (C.BOOKSET_ID IN
null) OR C.BOOKSET_ID in (
#{item}
)

