mapper.delete:
delete from PTL_SEC_RECEIVABLES SS where 1=1
AND EXISTS ( SELECT 1 FROM ( select b.bookset_id,/** 账套代码**/ /** 数据字典：收益类型.预期收益 02 **/ case when c.channel_id is null then case when b.acct_mode = '02' then b.acct_subject_id else nvl(d.portfolio_id,b.acct_subject_id) end else case when e.acct_mode='02' then e.acct_subject_id else nvl(f.portfolio_id,e.acct_subject_id) end end portfolio_id, /** 组合代码**/ c.channel_id, /** 通道代码**/ nvl(c.bookset_id,b.bookset_id) f_bookset_id /** 上级账套代码**/ from bok_bookset b /** 账套表**/ left join bok_bookset_re c on b.bookset_id = c.bookset_id_son /** 母子账套关系**/ left join fin_product_add d on b.acct_subject_id = d.finprod_id /** 标的类金融产品附属表**/ left join bok_bookset e on c.bookset_id = e.bookset_id /** 账套表**/ left join fin_product_add f on e.acct_subject_id = f.finprod_id /** 标的类金融产品附属表**/ WHERE B.START_DATE <= #{cdate,jdbcType=DATE} AND B.END_DATE > #{cdate,jdbcType=DATE} ) PRD WHERE 1=1 AND SS.PORTFOLIO_ID=PRD.portfolio_id
and f_bookset_id in
#{item.portfolioId,jdbcType=VARCHAR}
) and CDATE >= #{cdate,jdbcType=DATE}

